                    <div
                        className="flex items-center gap-0.5 px-1.5 py-1.5 bg-background/70 backdrop-blur-2xl border border-border/30 rounded-full shadow-[0_4px_24px_rgba(0,0,0,0.10)] ring-1 ring-white/[0.06]"
